import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Variant2 {
    static int uniqueCount(int[] arr, int start, int end) {
        boolean[] visited = new boolean[24];
        int count = 0;
        for (int i = start; i <= end; i++) {
            int val = arr[i];
            if (!visited[val]) {
                visited[val] = true;
                count++;
            }
        }
        return count;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int a = Integer.parseInt(st.nextToken());
        int b = Integer.parseInt(st.nextToken());
        int l = Integer.parseInt(st.nextToken()) - 1;
        int r = Integer.parseInt(st.nextToken()) - 1;

        int total = a + b;
        int repeatCount = 4;
        int[] pattern = new int[total * repeatCount];

        int blockOffset = l / total;
        l -= blockOffset * total;
        r -= blockOffset * total;

        int blockSize = (r - l + 1) / total;
        if (blockSize > 2) {
            r -= (blockSize - 2) * total;
        }

        int delta = a > b ? a - b : 1;
        for (int i = 0; i < repeatCount; i++) {
            for (int k = 0; k < a - delta; k++)
                pattern[(a + b) * i + k] = k;
            for (int k = 0; k < delta; k++)
                pattern[(a + b) * i + a - delta + k] = (i % 2 == 0) ? a - delta + k : a + k;
        }

        int minVal = a + a;
        for (int shift1 = 1; shift1 <= delta; shift1++) {
            for (int k = 0; k < b; k++)
                pattern[(a + b) * 0 + a + k] = pattern[(a + b) * 0 + a - shift1];
            for (int shift2 = 1; shift2 <= delta; shift2++) {
                for (int k = 0; k < b; k++)
                    pattern[(a + b) * 1 + a + k] = pattern[(a + b) * 1 + a - shift2];
                for (int shift3 = 1; shift3 <= delta; shift3++) {
                    for (int k = 0; k < b; k++)
                        pattern[(a + b) * 2 + a + k] = pattern[(a + b) * 2 + a - shift3];
                    for (int k = 0; k < b; k++)
                        pattern[(a + b) * 3 + a + k] = pattern[(a + b) * 3 + a - shift3];
                    minVal = Math.min(minVal, uniqueCount(pattern, l, r));
                }
            }
        }
        System.out.println(minVal);
    }
}
